#!/usr/bin/env bash
# Makes the seed inputs for the fuzz targets in fuzz/.
# Usage: scripts/fuzz-seeds.sh FIXTURES OUT [MADE]
#
# FIXTURES is fixtures/partition (generated by generate-fixtures.sh). OUT
# must not exist; it gets one flat file per seed, NAME.img.seed, made by
# scripts/experiments/exp-0012-seed.py with --recover: one for each
# FIXTURES/*.img except the two fat32-fragmented-* (almost every sector of
# each is non-zero, so a seed is about 66 MB, far over the 131,072-byte
# input limit the fuzz runs use).
#
# MADE, optional, is a directory holding the six volumes
# scripts/experiments/exp-0011-claims-images.sh writes (WORKDIR/claims/img).
# Each *.img in it gets two seeds: NAME.img.seed, the bare volume, and
# wrapped-NAME.img.seed, the volume wrapped in an MBR by
# scripts/experiments/mbr-wrap-sparse.py (ADR-0024), because the analysis
# reads a volume only inside a partition table.
#
# Every seed must be at most 131,072 bytes; a larger one is named and the
# script exits non-zero, as it does on any other failure.
set -euo pipefail

[ $# -eq 2 ] || [ $# -eq 3 ] || { echo "usage: fuzz-seeds.sh FIXTURES OUT [MADE]" >&2; exit 2; }
fx=$1; out=$2; made=${3:-}
here=$(cd "$(dirname "$0")" && pwd)
seed_py=$here/experiments/exp-0012-seed.py
wrap_py=$here/experiments/mbr-wrap-sparse.py
max_bytes=131072

[ -d "$fx" ] || { echo "FAIL FIXTURES is not a directory: $fx" >&2; exit 2; }
[ -z "$made" ] || [ -d "$made" ] || { echo "FAIL MADE is not a directory: $made" >&2; exit 2; }
[ -n "$out" ] && [ ! -e "$out" ] || { echo "FAIL OUT exists or is empty: $out" >&2; exit 2; }
mkdir -p "$out"

make_seed() { # IMAGE NAME: the seed OUT/NAME.seed, refused when over the limit
    python3 -I "$seed_py" "$1" "$out/$2.seed" --recover > /dev/null
    local size
    size=$(stat -c %s "$out/$2.seed")
    if [ "$size" -gt "$max_bytes" ]; then
        echo "FAIL seed $2.seed is $size bytes, over $max_bytes" >&2
        exit 1
    fi
}

fixtures=0
for img in "$fx"/*.img; do
    [ -e "$img" ] || { echo "FAIL no *.img in $fx" >&2; exit 1; }
    name=$(basename "$img")
    case $name in fat32-fragmented-*) continue ;; esac
    make_seed "$img" "$name"
    fixtures=$((fixtures + 1))
done

volumes=0
if [ -n "$made" ]; then
    # The wrapped copies are scratch inside OUT; each is removed once seeded.
    mkdir "$out/wrapped-tmp"
    for img in "$made"/*.img; do
        [ -e "$img" ] || { echo "FAIL no *.img in $made" >&2; exit 1; }
        name=$(basename "$img")
        make_seed "$img" "$name"
        python3 -I "$wrap_py" "$img" "$out/wrapped-tmp/$name" > /dev/null
        make_seed "$out/wrapped-tmp/$name" "wrapped-$name"
        rm -f -- "$out/wrapped-tmp/$name"
        volumes=$((volumes + 1))
    done
    rmdir "$out/wrapped-tmp"
fi

echo "$fixtures fixture seeds, $volumes made volumes ($((volumes * 2)) seeds), in $out"
